#include "core.hpp"
#include <fstream>
#include <iostream>
#include <algorithm>
using namespace scratcher;
namespace {
void check(bool value,const char*message){if(!value)throw std::runtime_error(message);}
struct Fixture {
 std::vector<uint8_t> data=std::vector<uint8_t>(0x1200);
 bool wide;Address base;size_t opt=0x98,dirs,section;
 explicit Fixture(bool bits64):wide(bits64),base(bits64?0x140000000ULL:0x400000),dirs(opt+(bits64?112:96)),section(opt+(bits64?240:224)){
  data[0]='M';data[1]='Z';put(0x3c,uint32_t(0x80));put(0x80,uint32_t(0x4550));put(0x84,uint16_t(wide?0x8664:0x14c));put(0x86,uint16_t(1));put(0x94,uint16_t(wide?240:224));
  put(opt,uint16_t(wide?0x20b:0x10b));put(opt+16,uint32_t(0x1f00));if(wide)put(opt+24,base);else put(opt+28,uint32_t(base));put(opt+60,uint32_t(0x200));put(opt+(wide?108:92),uint32_t(16));
  text(section,".text");put(section+8,uint32_t(0x1100));put(section+12,uint32_t(0x1000));put(section+16,uint32_t(0x1000));put(section+20,uint32_t(0x200));put(section+36,uint32_t(0x40000040));
 }
 template<class T>void put(size_t at,T value){check(at+sizeof(value)<=data.size(),"Fixture write bounds");std::memcpy(data.data()+at,&value,sizeof(value));}
 void text(size_t at,const std::string&value){check(at+value.size()+1<=data.size(),"Fixture text bounds");std::memcpy(data.data()+at,value.c_str(),value.size()+1);}
 size_t offset(uint32_t rva){return 0x200+rva-0x1000;}
 void directory(unsigned index,uint32_t rva,uint32_t size){put(dirs+index*8,rva);put(dirs+index*8+4,size);}
 void pointer(size_t at,Address value){if(wide)put(at,value);else put(at,uint32_t(value));}
 void cfg(unsigned stride=5){directory(10,0x1100,wide?148:92);auto at=offset(0x1100);put(at,uint32_t(wide?148:92));pointer(at+(wide?128:80),base+0x1200);pointer(at+(wide?136:84),3);put(at+(wide?144:88),uint32_t(0x400|((stride-4)<<28)));
  for(unsigned i=0;i<3;++i){put(offset(0x1200)+i*stride,uint32_t(0x1e00+i*0x10));if(stride>4)data[offset(0x1200)+i*stride+4]=uint8_t(i);}
 }
 void helpers(){cfg();pointer(offset(0x1100)+(wide?112:72),base+0x1800);pointer(offset(0x1100)+(wide?120:76),base+0x1810);pointer(offset(0x1800),base+0x1e00);pointer(offset(0x1810),base+0x1e30);data[offset(0x1e00)]=0xc3;data[offset(0x1e30)]=0xff;data[offset(0x1e30)+1]=0xe0;}
 void delay(bool rvaMode=true){directory(13,0x1300,64);auto at=offset(0x1300);put(at,uint32_t(rvaMode));auto field=[&](size_t f,uint32_t rva){put(at+f,uint32_t(rvaMode?rva:base+rva));};field(4,0x1400);field(12,0x1500);field(16,0x1600);text(offset(0x1400),"fixture.dll");
  auto width=wide?8:4;pointer(offset(0x1600),rvaMode?0x1700:base+0x1700);pointer(offset(0x1600)+width,wide?0x800000000000002aULL:0x8000002aULL);text(offset(0x1700)+2,"NamedFunction");pointer(offset(0x1500),base+0x1e00);pointer(offset(0x1500)+width,base+0x1e10);data[offset(0x1e00)]=0xc3;data[offset(0x1e10)]=0xc3;
 }
};
}
int main(){try{
 unsigned fixtureId=0;std::vector<std::filesystem::path> paths;
 auto test=[&](Fixture&fixture,const auto&verify){auto path=executableDir()/("pe-metadata-"+std::to_string(fixtureId++)+".exe");paths.push_back(path);{std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(fixture.data.data()),fixture.data.size());check(bool(out),"Write PE fixture");}{Binary binary(path);verify(binary);}std::filesystem::remove(path);};
 auto function=[](const Binary&b,Address va)->const Function*{auto it=std::find_if(b.functions.begin(),b.functions.end(),[&](auto&f){return f.va==va;});return it==b.functions.end()?nullptr:&*it;};
 for(bool wide:{false,true})for(unsigned stride:{4u,5u,7u}){Fixture f(wide);f.cfg(stride);test(f,[&](const Binary&b){check(b.functions.size()==4,"CFG imports all mapped targets and entry");check(!b.executable(f.base+0x1e00),"Declared nonexecute permission retained");check(b.analysisCode(f.base+0x1e00),"CFG candidate region eligible for analysis");check(b.analysisRanges.size()==1&&b.analysisRanges[0].second==f.base+0x2000,"Candidate excludes zero-filled section tail");check(function(b,f.base+0x1e00)->end==0,"CFG does not invent function ends");check(b.peMetadata["guard_cf"]["stride"]==stride,"CFG arbitrary stride");if(stride>4){check(function(b,f.base+0x1e10)->source=="Guard CF suppressed metadata","FID suppression provenance");check(function(b,f.base+0x1e20)->source=="Guard CF export-suppressed metadata","Export suppression provenance");}});}
 {Fixture f(true);f.cfg();f.put(f.offset(0x1200)+5,uint32_t(0x1df0));test(f,[&](const Binary&b){check(b.functions.size()==1&&!b.peMetadata["guard_cf"]["valid"].get<bool>(),"Unsorted CFG discarded transactionally");});}
 {Fixture f(true);f.cfg();f.pointer(f.offset(0x1100)+136,1000001);test(f,[&](const Binary&b){check(b.functions.size()==1&&!b.peMetadata["guard_cf"]["valid"].get<bool>(),"CFG excessive count bounded");});}
 {Fixture f(true);f.cfg();f.pointer(f.offset(0x1100)+128,f.base+0x1fff);test(f,[&](const Binary&b){check(b.functions.size()==1&&!b.peMetadata["guard_cf"]["valid"].get<bool>(),"CFG cross-file-backed-span rejected");});}
 {Fixture f(false);f.cfg();f.put(f.offset(0x1100),uint32_t(88));test(f,[&](const Binary&b){check(b.functions.size()==1&&!b.peMetadata["guard_cf"]["valid"].get<bool>(),"Short declared load configuration rejected");});}
 {Fixture f(true);f.cfg();f.put(f.opt+16,uint32_t(0));f.pointer(f.offset(0x1100)+136,1);f.data[f.offset(0x1200)+4]=1;test(f,[&](const Binary&b){check(function(b,f.base+0x1e00)!=nullptr,"Suppressed target preserved as symbol");check(b.analysisRanges.empty(),"Suppressed-only metadata does not promote section");});}
 {Fixture f(true);f.cfg();f.put(f.offset(0x1200)+5,uint32_t(0x1e00));test(f,[&](const Binary&b){check(b.functions.size()==3,"Duplicate CFG RVAs deduplicated");});}
 {Fixture f(true);f.cfg();f.put(f.offset(0x1200)+10,uint32_t(0x2050));test(f,[&](const Binary&b){check(b.functions.size()==3&&b.peMetadata["guard_cf"]["unmapped"]==1,"Zero-filled targets excluded");});}
 for(bool wide:{false,true}){Fixture f(wide);f.delay();test(f,[&](const Binary&b){check(b.imports.size()==2,"Delay imports recovered");check(b.imports[0].va==f.base+0x1500&&b.imports[0].module=="fixture.dll"&&b.imports[0].name=="NamedFunction","Named delay import and IAT identity");check(b.imports[1].name=="ordinal_42","Ordinal delay import");check(function(b,f.base+0x1e00)->source=="delay import thunk","Delay thunk seed");check(b.peMetadata["delay_imports"]["valid"].get<bool>(),"Valid delay table report");});}
 {Fixture f(false);f.delay(false);test(f,[&](const Binary&b){check(b.imports.size()==2&&b.imports[0].va==f.base+0x1500,"Legacy VA delay descriptor and hint pointers");});}
 {Fixture f(true);f.delay();f.pointer(f.offset(0x1600),0x100001700ULL);test(f,[&](const Binary&b){check(b.imports.empty()&&b.functions.size()==1&&!b.peMetadata["delay_imports"]["valid"].get<bool>(),"Invalid 64-bit delay RVA does not truncate");});}
 {Fixture f(true);f.delay();f.put(f.offset(0x1300),uint32_t(3));test(f,[&](const Binary&b){check(b.imports.empty()&&!b.peMetadata["delay_imports"]["valid"].get<bool>(),"Reserved delay attributes rejected");});}
 {Fixture f(false);f.delay();f.put(f.offset(0x1300)+16,uint32_t(0x1ff8));f.put(f.offset(0x1ff8),uint32_t(0x80000001));f.put(f.offset(0x1ffc),uint32_t(0x80000002));test(f,[&](const Binary&b){check(b.imports.empty()&&!b.peMetadata["delay_imports"]["valid"].get<bool>(),"Unterminated delay name table rejected transactionally");});}
 {Fixture f(true);f.cfg();f.put(f.section+36,uint32_t(0x60000020));f.directory(3,0x1c00,12);f.put(f.offset(0x1c00),uint32_t(0x1e00));f.put(f.offset(0x1c00)+4,uint32_t(0x1e10));test(f,[&](const Binary&b){check(function(b,f.base+0x1e00)->source=="unwind metadata"&&function(b,f.base+0x1e00)->end==f.base+0x1e10,"Duplicate CFG preserves unwind bounds and provenance");});}
 {Fixture f(true);f.delay();f.put(f.section+36,uint32_t(0x60000020));f.directory(3,0x1c00,12);f.put(f.offset(0x1c00),uint32_t(0x1e00));f.put(f.offset(0x1c00)+4,uint32_t(0x1e10));test(f,[&](const Binary&b){auto*target=function(b,f.base+0x1e00);check(target&&target->source=="delay import thunk"&&target->name=="delay_NamedFunction","Named delay thunk outranks generic unwind symbol");check(target->end==f.base+0x1e10,"Named delay thunk retains validated unwind bounds");});}
 for(bool wide:{false,true}){Fixture f(wide);f.helpers();test(f,[&](const Binary&b){auto*checkTarget=function(b,f.base+0x1e00);auto*dispatchTarget=function(b,f.base+0x1e30);check(b.functions.size()==5,"Helper-only function target adds genuine unique record");check(checkTarget&&checkTarget->name=="_guard_check_icall"&&checkTarget->source=="Guard CF helper pointer","CFG helper name outranks generic table seed");check(dispatchTarget&&dispatchTarget->name=="_guard_dispatch_icall"&&dispatchTarget->end==0,"Dispatch pointer dereference creates named target without fabricated body");check(!function(b,f.base+0x1800)&&!function(b,f.base+0x1810),"Pointer slots are not function seeds");check(b.peMetadata["guard_cf_helpers"]["imported"]==2&&b.peMetadata["guard_cf_helpers"]["valid"].get<bool>(),"Helper import evidence counts");check(b.peMetadata["guard_cf_helpers"]["entries"][1]["pointer_slot"]==hex(f.base+0x1810),"Helper provenance includes slot");check(!b.executable(f.base+0x1e30)&&b.analysisCode(f.base+0x1e30),"Helper candidate eligibility preserves actual permissions");});}
 {Fixture f(true);f.helpers();f.put(f.section+36,uint32_t(0x60000020));f.directory(3,0x1c00,12);f.put(f.offset(0x1c00),uint32_t(0x1e00));f.put(f.offset(0x1c00)+4,uint32_t(0x1e10));test(f,[&](const Binary&b){auto*target=function(b,f.base+0x1e00);check(target&&target->name=="_guard_check_icall"&&target->source=="Guard CF helper pointer"&&target->end==f.base+0x1e10,"Helper label preserves duplicate unwind body bounds");});}
 {Fixture f(true);f.helpers();f.pointer(f.offset(0x1100)+120,f.base+0x1fff);test(f,[&](const Binary&b){check(b.functions.size()==4&&!function(b,f.base+0x1e30),"Cross-span helper slot does not import target");check(!b.peMetadata["guard_cf_helpers"]["valid"].get<bool>()&&b.peMetadata["guard_cf_helpers"]["imported"]==1,"Malformed helper slot gives warning without losing valid helper");});}
 {Fixture f(false);f.helpers();f.pointer(f.offset(0x1810),f.base+0x1810);test(f,[&](const Binary&b){check(b.functions.size()==4&&!function(b,f.base+0x1810),"Self-referencing helper pointer rejected");check(!b.peMetadata["guard_cf_helpers"]["valid"].get<bool>(),"Self-reference reported as malformed metadata");});}
 {Fixture f(true);f.helpers();f.pointer(f.offset(0x1810),f.base+0x2050);test(f,[&](const Binary&b){check(b.functions.size()==4&&!function(b,f.base+0x2050),"Zero-filled helper target is not code evidence");check(!b.peMetadata["guard_cf_helpers"]["valid"].get<bool>(),"Unbacked target warning retained");});}
 {Fixture f(false);f.helpers();f.put(f.offset(0x1100),uint32_t(72));test(f,[&](const Binary&b){check(b.functions.size()==1&&b.peMetadata["guard_cf_helpers"]["imported"]==0,"Absent fields in older declared structure are not read");});}
 {Fixture f(true);f.helpers();f.directory(10,0x1100,112);test(f,[&](const Binary&b){check(b.functions.size()==1&&!b.peMetadata["guard_cf_helpers"]["valid"].get<bool>(),"Directory size bounds override larger declared structure");});}
 for(bool wide:{false,true}){Fixture f(wide);f.put(f.opt+16,uint32_t(0));test(f,[&](const Binary&b){check(b.entry==0&&b.functions.empty(),"PE with no entry point does not invent a header function");check(b.analysisRanges.empty()&&!b.analysisCode(b.base),"PE headers stay data when entry metadata is absent");});}
 for(auto&path:paths)std::filesystem::remove(path);std::cout<<"PASS: PE32/PE64 CFG strides, suppression, permission preservation, file-backed bounds, delay RVA/VA names, ordinals and malformed tables\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
